   58:     BigNumber Verifier(const BigNumber& s, const std::string& passwordHashHex)
   59:     {
   60:         BigNumber I;
   61:         I.SetHexStr(passwordHashHex.c_str());
   62: 
   63:         // In case of leading zeros in the stored hash, restore them: asking for the full
   64:         // digest width pads at the front, where the minimal encoding would have lost them.
   65:         uint8 digest[DigestWidth];
   66:         std::memset(digest, 0, DigestWidth);
   67:         if (I.GetNumBytes() <= DigestWidth)
   68:         {
   69:             std::memcpy(digest, I.AsByteArray(DigestWidth), DigestWidth);
   70:         }
   71:         std::reverse(digest, digest + DigestWidth);
