   73:         // x = H(s | H(USER:PASS)) over the whole salt. A short salt here is not a failed
   74:         // login but a verifier stored against a byte string the client will never
   75:         // produce, so that account is broken for good rather than until the next attempt.
   76:         Sha1Hash sha;
   77:         UpdateFixed(sha, s, SaltWidth);
   78:         sha.UpdateData(digest, DigestWidth);
