  138:             half[i] = t[i * 2 + 1];
  139:         }
  140:         sha.Initialize();
  141:         sha.UpdateData(half, EphemeralWidth / 2);
  142:         sha.Finalize();
  143:         for (int i = 0; i < DigestWidth; ++i)
  144:         {
  145:             vK[i * 2 + 1] = sha.GetDigest()[i];
  146:         }
