   33: /**
   34:  * @brief The SRP6 arithmetic of the login handshake, as the 4.3.4 client computes it.
   35:  *
   36:  * Pure functions over BigNumber and SHA-1: no socket, no database, no state. Every
   37:  * quantity is hashed at the width the protocol fixes for it, never at the width a
   38:  * value happens to have -- the client hashes the same bytes it sent and received,
   39:  * and those are always full width.
   40:  *
   41:  * Kept separate from AuthSocket so the calculation the server runs is the one the
   42:  * tests run: the golden vectors in realmd's test suite go through these functions.
   43:  */
   44: namespace Srp6
   45: {
   46:     constexpr int EphemeralWidth  = 32;   ///< N, A, B
   47:     constexpr int SessionKeyWidth = 40;   ///< K
   48:     constexpr int GeneratorWidth  = 1;    ///< g
   49:     constexpr int ReconnectWidth  = 16;   ///< R1 and the server's reconnect challenge
   50:     constexpr int SaltWidth       = 32;   ///< s
   51:     constexpr int DigestWidth     = 20;   ///< SHA-1
   52: 
   53:     /// The 256-bit safe prime the client and server agree on.
   54:     BigNumber Modulus();
   55:     /// The generator, 7.
   56:     BigNumber Generator();
   57: 
   58:     /**
   59:      * @brief The password verifier stored in the account row.
   60:      *
   61:      * x = H(s | H(USERNAME:PASSWORD)), v = g^x mod N. `passwordHashHex` is the hex
   62:      * text of H(USERNAME:PASSWORD) exactly as the account row stores it; a hash
   63:      * with leading zeros is restored to its full 20 bytes before hashing.
   64:      */
   65:     BigNumber Verifier(const BigNumber& s, const std::string& passwordHashHex);
   66: 
   67:     /// B = (3v + g^b) mod N for the server's private ephemeral b.
   68:     BigNumber ServerEphemeral(const BigNumber& v, const BigNumber& b);
   69: 
   70:     /// The client's ephemeral A is rejected when A mod N is zero.
   71:     bool IsAcceptableClientEphemeral(const BigNumber& A);
   72: 
   73:     /// u = H(A | B), both at ephemeral width.
   74:     BigNumber Scrambler(const BigNumber& A, const BigNumber& B);
   75: 
   76:     /**
   77:      * @brief The 40-byte session key.
   78:      *
   79:      * S = (A * v^u)^b mod N, then the even and odd bytes of S are hashed separately
   80:      * and the two digests interleaved into K.
   81:      */
   82:     BigNumber SessionKey(const BigNumber& A, const BigNumber& v, const BigNumber& u, const BigNumber& b);
   83: 
   84:     /**
   85:      * @brief M1 as the client computes it: H((H(N) xor H(g)) | H(login) | s | A | B | K).
   86:      * @param out 20 bytes.
   87:      */
   88:     void ClientProof(const std::string& login, const BigNumber& s, const BigNumber& A,
   89:                      const BigNumber& B, const BigNumber& K, uint8* out);
   90: 
   91:     /**
   92:      * @brief M2 = H(A | M1 | K), the server's answer to a valid M1.
   93:      * @param clientProof the 20 bytes of M1.
   94:      * @param out 20 bytes.
   95:      */
   96:     void ServerProof(const BigNumber& A, const uint8* clientProof, const BigNumber& K, uint8* out);
   97: 
   98:     /**
   99:      * @brief The reconnect proof: H(login | R1 | challenge | K).
  100:      * @param clientData the 16 bytes of R1 from the client.
  101:      * @param challenge the 16-byte value the server sent with the reconnect challenge.
  102:      * @param out 20 bytes.
  103:      */
  104:     void ReconnectProof(const std::string& login, const uint8* clientData,
  105:                         const BigNumber& challenge, const BigNumber& K, uint8* out);
  106: }
